const VOCAB_STORAGE_KEY = 'bingo_custom_topics_v1';

export function getLoadedTopics(): Topic[] {
  try {
    const saved = localStorage.getItem(VOCAB_STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved) as Topic[];
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed;
      }
    }
  } catch (err) {
    console.warn('Could not read custom topics from localStorage:', err);
  }
  return INITIAL_TOPICS;
}

export function saveTopics(topics: Topic[]): void {
  try {
    localStorage.setItem(VOCAB_STORAGE_KEY, JSON.stringify(topics));
  } catch (err) {
    console.error('Failed to save topics to localStorage:', err);
  }
}

export function resetTopicsToDefault(): Topic[] {
  try {
    localStorage.removeItem(VOCAB_STORAGE_KEY);
  } catch (err) {
    console.error('Failed to clear topics from localStorage:', err);
  }
  return INITIAL_TOPICS;
}
